import logging

def test_foo(caplog):
    caplog.set_level(42)

def test_bar(caplog):
    # The handler level should be restored to its original value (NOTSET = 0)
    assert caplog.handler.level == logging.NOTSET

import requests

def test_dot_example_com_invalid_url():
    try:
        requests.get("http://.example.com")
    except requests.exceptions.InvalidURL as e:
        assert "URL has an invalid label." in str(e)
    except Exception as e:
        raise AssertionError(f"Expected InvalidURL but got {type(e).__name__}: {e}")
